import asyncio
import contextlib
import importlib
import sys
import types
import uuid
from functools import lru_cache
from importlib.util import find_spec
from typing import (
    TYPE_CHECKING,
    Any,
    ClassVar,
    Dict,
    Optional,
    Text,
)

import structlog
from rasa_sdk.executor import ActionExecutor, CollectingDispatcher
from rasa_sdk.interfaces import ActionMissingDomainException

import rasa
from rasa.core.actions.action_exceptions import DomainNotFound
from rasa.core.actions.constants import (
    STREAMING_QUEUE_MAX_SIZE,
    STREAMING_RESPONSE_ID_KEY,
)
from rasa.core.actions.custom_action_executor import (
    CustomActionExecutor,
    aggregate_streamed_payloads,
    dispatch_stream_chunk,
    warn_on_duplicate_streamed_responses,
)
from rasa.shared.core.domain import Domain
from rasa.shared.core.trackers import DialogueStateTracker, EventVerbosity
from rasa.shared.exceptions import RasaException
from rasa.utils.endpoints import EndpointConfig

if TYPE_CHECKING:
    from rasa.core.channels.channel import OutputChannel

structlogger = structlog.get_logger(__name__)


class DirectCustomActionExecutor(CustomActionExecutor):
    _actions_module_registered: ClassVar[bool] = False
    _actions_module_name: ClassVar[Optional[str]] = None
    supports_streaming: ClassVar[bool] = True

    def __init__(self, action_name: str, action_endpoint: EndpointConfig):
        """Initializes the direct custom action executor.

        Args:
            action_name: Name of the custom action.
            action_endpoint: The endpoint to execute custom actions.
        """
        self.action_name = action_name
        self.action_endpoint = action_endpoint
        self.action_executor = self._create_action_executor()

    @staticmethod
    @lru_cache(maxsize=1)
    def _create_action_executor() -> ActionExecutor:
        """Creates and returns a cached ActionExecutor instance.

        Returns:
            ActionExecutor: The cached ActionExecutor instance.
        """
        return ActionExecutor()

    def register_actions_from_a_module(self) -> None:
        """Registers actions from the specified module if not already registered.

        This method checks if the actions module has already been registered to prevent
        duplicate registrations. If not registered, it attempts to register the actions
        module specified in the action endpoint configuration. If the module does not
        exist, it raises a RasaException.

        Raises:
            RasaException: If the actions module specified does not exist.
        """
        if DirectCustomActionExecutor._actions_module_registered:
            return

        raw = self.action_endpoint.actions_module
        if isinstance(raw, types.ModuleType):
            module_name = raw.__name__
        elif isinstance(raw, str):
            module_name = raw
        else:
            raise RasaException(
                "No 'actions_module' configured in your action endpoint. "
                "Please set it in your `endpoints.yml` file."
            )

        if not find_spec(module_name):
            raise RasaException(
                f"You've provided the custom actions module '{module_name}' "
                f"to run directly by the rasa server, however this module does "
                f"not exist. Please check for typos in your `endpoints.yml` file."
            )

        self.action_executor.register_package(module_name)
        DirectCustomActionExecutor._actions_module_registered = True
        DirectCustomActionExecutor._actions_module_name = module_name

    @classmethod
    def reset_action_registration(cls) -> None:
        """Purge cached action modules and re-register from the filesystem.

        Clears `sys.modules` entries for the actions package, replaces
        the LRU-cached `ActionExecutor` with a fresh instance, and
        re-imports the package from disk. After completion the executor
        is ready and `_actions_module_registered` remains `True`.

        No-op when no actions module has been registered yet.
        """
        if not cls._actions_module_registered:
            return

        module_name = cls._actions_module_name

        # Purge cached modules so importlib re-reads from disk
        if module_name:
            modules_to_remove = [
                name
                for name in sys.modules
                if name == module_name or name.startswith(module_name + ".")
            ]
            for name in modules_to_remove:
                del sys.modules[name]

        # Replace the cached ActionExecutor with a fresh instance
        cls._create_action_executor.cache_clear()

        # Drop the import machinery's directory caches so find_spec() reflects
        # files deleted on disk instead of returning a stale ModuleSpec.
        importlib.invalidate_caches()

        if module_name and find_spec(module_name):
            # Module still on disk — re-register and clean up orphans
            executor = cls._create_action_executor()
            try:
                executor.register_package(module_name)
            except Exception:
                # Registration failed (e.g. syntax error in an action file).
                # Discard the partially-registered executor so the retry
                # path in register_actions_from_a_module gets a clean one.
                cls._create_action_executor.cache_clear()
                cls._actions_module_registered = False
                cls._actions_module_name = None
                structlogger.warning(
                    "action.direct_custom_action_executor.reset_failed",
                    actions_module=module_name,
                )
                raise
            cls._purge_orphaned_actions(executor)
            cls._actions_module_name = module_name
            cls._actions_module_registered = True
        else:
            # Module was deleted — let run() surface the error
            cls._actions_module_name = None
            cls._actions_module_registered = False

        structlogger.debug(
            "action.direct_custom_action_executor.registration_reset",
            actions_module=module_name,
        )

    @staticmethod
    def _purge_orphaned_actions(executor: ActionExecutor) -> None:
        """Remove actions whose source modules are no longer loaded.

        After re-registration, `Action` subclasses from deleted files
        may still be in Python's class hierarchy and get re-registered.
        This removes any whose defining module is not in `sys.modules`.

        Args:
            executor: The `ActionExecutor` to clean up.
        """
        # Orphaned Action subclasses from deleted files may linger in
        # Python's class hierarchy until garbage-collected, causing
        # register_package to re-register them on the fresh executor.
        # Identify them by checking if their defining module is loaded.
        stale_action_names = [
            action_name
            for action_name, action_fn in executor.actions.items()
            if (
                getattr(action_fn, "__self__", None) is not None
                and type(action_fn.__self__).__module__ not in sys.modules
            )
        ]

        for action_name in stale_action_names:
            del executor.actions[action_name]
            structlogger.debug(
                "action.direct_custom_action_executor.removed_orphaned_action",
                action_name=action_name,
            )

    async def run(
        self,
        tracker: "DialogueStateTracker",
        domain: "Domain",
        include_domain: bool = False,
    ) -> Dict[Text, Any]:
        """Executes the custom action directly.

        Args:
            tracker: The current state of the dialogue.
            domain: The domain object containing domain-specific information.
            include_domain: If True, the domain is included in the request.

        Returns:
            The response from the execution of the custom action.

        Raises:
            RasaException: If the actions module specified does not exist.
        """
        structlogger.debug(
            "action.direct_custom_action_executor.run",
            action_name=self.action_name,
        )

        # Register actions module if not already registered.
        # This is done here instead of __init__ to allow proper
        # exception handling and avoid hanging conversations.
        self.register_actions_from_a_module()
        self.action_executor.reload()

        tracker_state = tracker.current_state(EventVerbosity.ALL)
        action_call = {
            "next_action": self.action_name,
            "sender_id": tracker.sender_id,
            "tracker": tracker_state,
            "version": rasa.__version__,
        }

        if domain:
            action_call["domain"] = domain.as_dict()

        result = await self.action_executor.run(action_call)
        return result.model_dump() if result else {}

    async def run_streaming(
        self,
        tracker: "DialogueStateTracker",
        domain: "Domain",
        output_channel: "OutputChannel",
        include_domain: bool = False,
    ) -> Dict[Text, Any]:
        """Executes the custom action directly with streaming output.

        Runs the action via :meth:`ActionExecutor.run`, consuming
        chunk events from the sink queue as they are produced.  Each text
        chunk is forwarded to *output_channel* in real time so the end user
        receives tokens incrementally.

        Chunk events emitted by the SDK:

        * ``stream_start``  -- forwarded as
          :meth:`~OutputChannel.send_response_chunk_start`.
        * ``stream_chunk``  -- routed by
          :func:`~rasa.core.actions.custom_action_executor.dispatch_stream_chunk`:
          rich payloads (buttons, image, attachment, custom, elements) are
          delivered via :meth:`~OutputChannel.send_response`; plain text
          payloads are forwarded as incremental tokens via
          :meth:`~OutputChannel.send_response_chunk`.
        * ``stream_end``    -- forwarded as
          :meth:`~OutputChannel.send_response_chunk_end`.
        * ``stream_done``   -- terminal sentinel carrying the full result;
          not forwarded to the channel.

        Note: when the SDK sink is attached, ``stream_end`` does **not** call
        ``utter_message`` on the dispatcher, so the streamed text does not
        appear in ``responses``.  No deduplication is therefore needed in
        ``RemoteAction._utter_responses``.

        If the action raises an exception (e.g.
        :class:`~rasa_sdk.interfaces.ActionExecutionRejection`) the background
        task fails before placing ``stream_done`` on the queue.  A done-callback
        puts an ``_error`` sentinel on the queue so the consumer loop always
        terminates and the original exception is re-raised.

        Args:
            tracker: The current state of the dialogue.
            domain: The domain object containing domain-specific information.
            output_channel: The output channel to forward streaming chunks to.
            include_domain: Ignored for the direct executor — the domain is always
                included because the SDK runs in-process and there is no network
                payload overhead to avoid.

        Returns:
            The final ``{events, responses}`` dict from the completed action.

        Raises:
            RasaException: If the actions module specified does not exist.
        """
        structlogger.debug(
            "action.direct_custom_action_executor.run_streaming",
            action_name=self.action_name,
        )

        self.register_actions_from_a_module()
        self.action_executor.reload()

        tracker_state = tracker.current_state(EventVerbosity.ALL)
        action_call = {
            "next_action": self.action_name,
            "sender_id": tracker.sender_id,
            "tracker": tracker_state,
            "version": rasa.__version__,
        }

        if domain:
            action_call["domain"] = domain.as_dict()

        # Pre-construct the dispatcher so _consume_stream_events can call
        # cancel_stream() on it if the voice channel signals an interruption.
        # ActionExecutor.run() accepts an optional `dispatcher` kwarg so the
        # caller can hold a reference before the action starts (SDK >= PF-1133).
        dispatcher = CollectingDispatcher()
        sink: asyncio.Queue = asyncio.Queue(maxsize=STREAMING_QUEUE_MAX_SIZE)
        executor_task = asyncio.create_task(
            self.action_executor.run(action_call, sink=sink, dispatcher=dispatcher)
        )

        # If the task fails before placing stream_done (e.g. ActionExecutionRejection),
        # put an error sentinel so the consumer loop below always terminates.
        async def _put_error_on_sink(exc: BaseException) -> None:
            await sink.put({"event": "stream_error", "exception": exc})

        # Keeps strong references to fire-and-forget tasks so they are not
        # garbage-collected before they complete (required by RUF006).
        _background_tasks: set = set()

        def _on_task_done(task: "asyncio.Task[Any]") -> None:
            if task.cancelled():
                return
            exc = task.exception()
            if exc is None:
                return
            # The SDK already puts {"event": "stream_error", "exception": exc}
            # before re-raising so the consumer loop can exit cleanly.  This
            # callback is a last-resort backstop for unexpected paths where the
            # SDK skips that step (e.g. in very old SDK versions or mocks).
            try:
                sink.put_nowait({"event": "stream_error", "exception": exc})
            except asyncio.QueueFull:
                bg = asyncio.create_task(_put_error_on_sink(exc))
                _background_tasks.add(bg)
                bg.add_done_callback(_background_tasks.discard)

        executor_task.add_done_callback(_on_task_done)

        try:
            final_result = await self._consume_stream_events(
                sink, output_channel, tracker.sender_id, dispatcher
            )
            await executor_task
            return final_result
        except BaseException as exc:
            # Cancel the background SDK task so it does not block forever on a
            # full sink queue after the consumer has already exited.
            executor_task.cancel()
            with contextlib.suppress(asyncio.CancelledError, Exception):
                await executor_task
            raise exc

    def _raise_for_sdk_error(self, exc: BaseException) -> None:
        """Re-raise *exc*, translating domain-missing errors to :class:`DomainNotFound`.

        Args:
            exc: The exception placed on the sink by the SDK background task.

        Raises:
            DomainNotFound: When *exc* is an :class:`ActionMissingDomainException`.
        """
        if isinstance(exc, ActionMissingDomainException):
            raise DomainNotFound() from exc
        raise exc

    async def _consume_stream_events(
        self,
        sink: "asyncio.Queue[Dict[Text, Any]]",
        output_channel: "OutputChannel",
        sender_id: str,
        dispatcher: Optional[CollectingDispatcher] = None,
    ) -> Dict[Text, Any]:
        """Consume SDK stream events from *sink* until ``stream_done`` is received.

        Processes each event type in order, forwarding chunks to *output_channel*
        in real time.  Raises the original exception if an ``stream_error`` sentinel
        is received.

        When the voice channel signals an interruption
        (``output_channel.stream_interrupted`` is set to ``True``
        after a chunk dispatch), this method calls
        ``dispatcher.cancel_stream()`` to tell the SDK action to stop producing
        chunks and run ``stream_end()`` with the heard-only content.  The loop
        continues draining the queue in discard mode — it does **not** cancel the
        background task — so that ``stream_done`` arrives normally and
        ``final_result`` contains only the heard responses and all action events.

        Args:
            sink: The queue populated by the SDK ``ActionExecutor.run``
                background task.
            output_channel: The output channel to forward streaming chunks to.
            sender_id: The sender ID of the current conversation.
            dispatcher: The pre-constructed ``CollectingDispatcher`` shared with
                the SDK task.  When supplied and an interruption is detected,
                ``cancel_stream()`` is called on it.

        Returns:
            The final ``{events, responses}`` dict from the completed action.
        """
        final_result: Dict[Text, Any] = {}
        streamed_payloads: list[Dict[Text, Any]] = []
        # The direct (in-process) SDK sink does not carry a response_id on its
        # chunk events (unlike the gRPC transport), so we derive a streaming
        # response id from the stream_start boundary: a fresh UUID is generated
        # on each stream_start and stamped onto every chunk's stored payload so
        # that aggregate_streamed_payloads does not merge text across separate
        # streaming responses opened in the same action run.
        streaming_response_id: Optional[str] = None
        discarding = False
        # True while a chunk session is open; used by the except block to
        # decide whether cleanup is needed.
        stream_session_active = False

        try:
            while True:
                chunk: Dict[Text, Any] = await sink.get()
                event = chunk.get("event")
                if event == "stream_done":
                    final_result = self._build_stream_done_result(
                        chunk, streamed_payloads, discarding
                    )
                    break
                if event == "stream_error":
                    self._raise_for_sdk_error(chunk["exception"])
                if event == "stream_start":
                    streaming_response_id = uuid.uuid4().hex
                # Mark session open *before* the await so cleanup fires even if
                # send_response_chunk_start raises.  stream_end is cleared
                # *after* the handler/drain await so a raise there still
                # triggers cleanup.
                stream_session_active = {
                    "stream_start": True,
                }.get(event, stream_session_active)

                if not discarding:
                    discarding = not await self._handle_active_stream_event(
                        event,
                        chunk,
                        output_channel,
                        sender_id,
                        streamed_payloads,
                        streaming_response_id,
                        dispatcher,
                    )
                    stream_session_active = {
                        "stream_end": False,
                    }.get(event, stream_session_active)
                elif event == "stream_end":
                    # Even in drain mode we must close the TTS session when
                    # stream_end arrives so the audio_sender_task releases the
                    # voice-channel WebSocket before the next utterance opens a
                    # new consumer (mirrors the gRPC executor's drain handler for
                    # chunk_end).
                    with contextlib.suppress(BaseException):
                        await output_channel.send_response_chunk_end(sender_id)
                    stream_session_active = False
        except BaseException as exc:
            # Close the chunk session only when one was actually opened, so
            # channels like VoiceOutputChannel do not receive an END marker
            # when the SDK failed before stream_start.
            if stream_session_active:
                with contextlib.suppress(BaseException):
                    await output_channel.send_response_chunk_end(sender_id)
            raise exc

        return final_result

    async def _handle_active_stream_event(
        self,
        event: Optional[Text],
        chunk: Dict[Text, Any],
        output_channel: "OutputChannel",
        sender_id: str,
        streamed_payloads: list,
        streaming_response_id: Optional[str],
        dispatcher: Optional[CollectingDispatcher],
    ) -> bool:
        """Dispatch a single active (non-done, non-error) stream event.

        Args:
            event: The event type string from the SDK chunk.
            chunk: The full chunk dict from the sink queue.
            output_channel: Output channel to forward streaming events to.
            sender_id: Conversation sender ID.
            streamed_payloads: Accumulator for dispatched payloads, each tagged
                with its ``streaming_response_id`` so aggregation does not merge
                across streaming-response boundaries. Mutated.
            streaming_response_id: UUID hex string for the current streaming
                response (a fresh value is generated on each stream_start),
                stamped onto each chunk's stored payload.
            dispatcher: SDK dispatcher; ``cancel_stream()`` called on interruption.

        Returns:
            ``True`` if streaming should continue (no interruption detected),
            ``False`` if the voice channel signalled a barge-in and the caller
            should switch to drain mode.
        """
        if event == "stream_start":
            structlogger.debug(
                "action.direct_custom_action_executor.run_streaming.stream_start",
                action_name=self.action_name,
            )
            await output_channel.send_response_chunk_start(sender_id)
        elif event == "stream_chunk":
            payload = {
                key: value
                for key, value in chunk.items()
                if key not in ("event", "response_id")
            }
            structlogger.debug(
                "action.direct_custom_action_executor.run_streaming.chunk",
                action_name=self.action_name,
            )
            await dispatch_stream_chunk(output_channel, sender_id, payload)
            # Stamp the current streaming response id on the stored payload (not
            # on the one dispatched to the channel) so aggregation does not merge
            # text across separate streaming responses opened in the same run.
            streamed_payloads.append(
                {**payload, STREAMING_RESPONSE_ID_KEY: streaming_response_id}
            )
            # Check if the voice channel dropped this chunk due to a
            # user barge-in.  If so, signal the SDK action to stop
            # producing and switch to drain mode.
            return not self._check_and_cancel_stream(
                output_channel,
                dispatcher,
                "action.direct_custom_action_executor.run_streaming.stream_interrupted",
            )
        elif event == "stream_end":
            structlogger.debug(
                "action.direct_custom_action_executor.run_streaming.stream_end",
                action_name=self.action_name,
            )
            await output_channel.send_response_chunk_end(sender_id)
            # send_response_chunk_end awaits the TTS audio task, so by
            # the time it returns stream_interrupted is reliable (covers
            # the fast-LLM/slow-TTS case where all chunks pre-arrived).
            return not self._check_and_cancel_stream(
                output_channel,
                dispatcher,
                "action.direct_custom_action_executor"
                ".run_streaming.stream_interrupted_on_stream_end",
            )
        return True

    def _check_and_cancel_stream(
        self,
        output_channel: "OutputChannel",
        dispatcher: Optional[CollectingDispatcher],
        log_event_key: str,
    ) -> bool:
        """Check for a voice-channel interruption and cancel the stream if detected.

        Args:
            output_channel: Output channel to check the ``stream_interrupted`` flag on.
            dispatcher: SDK dispatcher to cancel; ``None`` is a no-op.
            log_event_key: Structlog event key emitted when an interruption is detected.

        Returns:
            ``True`` if an interruption was detected, ``False`` otherwise.
        """
        if not getattr(output_channel, "stream_interrupted", False):
            return False
        structlogger.debug(log_event_key, action_name=self.action_name)
        if dispatcher is not None:
            dispatcher.cancel_stream()
        return True

    def _build_stream_done_result(
        self,
        chunk: Dict[Text, Any],
        streamed_payloads: list,
        discarding: bool,
    ) -> Dict[Text, Any]:
        """Build the final result dict when a ``stream_done`` event is received.

        Injects streamed payloads into ``responses`` so that
        :meth:`~rasa.core.actions.action.RemoteAction.run` can create
        ``BotUttered`` tracker events for them. Consecutive text tokens from the
        same streaming response are aggregated into a single ``BotUttered`` so the
        transcript shows one composed message; ``STREAMED_CHUNK_KEY`` prevents
        ``_send_bot_messages`` from re-delivering them to the output channel.

        Args:
            chunk: The ``stream_done`` chunk from the sink queue.
            streamed_payloads: All chunk payloads dispatched during the stream,
                each tagged with its ``streaming_response_id``.
            discarding: Whether the stream was interrupted (logged for observability).

        Returns:
            The final ``{events, responses}`` dict.
        """
        sdk_result = chunk.get("result")
        final_result: Dict[Text, Any] = sdk_result.model_dump() if sdk_result else {}
        warn_on_duplicate_streamed_responses(
            action_name=self.action_name,
            streamed_payloads=streamed_payloads,
            final_responses=final_result.get("responses", []),
        )
        if streamed_payloads:
            tagged = aggregate_streamed_payloads(streamed_payloads)
            final_result["responses"] = tagged + final_result.get("responses", [])
            structlogger.debug(
                "action.direct_custom_action_executor"
                ".run_streaming.final_result_with_streamed_chunks",
                action_name=self.action_name,
                streamed_count=len(streamed_payloads),
                interrupted=discarding,
            )
        return final_result
